import{_ as e,H as i,f as a,i as t}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"直播回放 | 当架构遇到大模型：毁灭，还是重生","description":"","frontmatter":{},"headers":[{"level":3,"title":"技术演进的本质","slug":"技术演进的本质","link":"#技术演进的本质","children":[]},{"level":3,"title":"架构与智能化的融合","slug":"架构与智能化的融合","link":"#架构与智能化的融合","children":[]},{"level":3,"title":"大模型对架构的影响：重生而非毁灭","slug":"大模型对架构的影响-重生而非毁灭","link":"#大模型对架构的影响-重生而非毁灭","children":[]},{"level":3,"title":"传统架构的痛点分析","slug":"传统架构的痛点分析","link":"#传统架构的痛点分析","children":[]},{"level":3,"title":"智能原生架构方法论（四维框架重构）","slug":"智能原生架构方法论-四维框架重构","link":"#智能原生架构方法论-四维框架重构","children":[]},{"level":3,"title":"智能体的本质与设计范式","slug":"智能体的本质与设计范式","link":"#智能体的本质与设计范式","children":[]},{"level":3,"title":"新一代中台建设","slug":"新一代中台建设","link":"#新一代中台建设","children":[]},{"level":3,"title":"业务中台","slug":"业务中台","link":"#业务中台","children":[]},{"level":3,"title":"数据中台","slug":"数据中台","link":"#数据中台","children":[]},{"level":3,"title":"关键趋势与思想","slug":"关键趋势与思想","link":"#关键趋势与思想","children":[]},{"level":3,"title":"架构演进策略","slug":"架构演进策略","link":"#架构演进策略","children":[]},{"level":3,"title":"架构师的未来","slug":"架构师的未来","link":"#架构师的未来","children":[]}],"relativePath":"智能原生架构实战/直播回放｜当架构遇到大模型：毁灭，还是重生.md","filePath":"智能原生架构实战/直播回放｜当架构遇到大模型：毁灭，还是重生.md","lastUpdated":1795558194000}'),r={name:"智能原生架构实战/直播回放｜当架构遇到大模型：毁灭，还是重生.md"};function n(p,l,h,s,o,E){return i(),a("div",null,[...l[0]||(l[0]=[t('<h1 id="直播回放-当架构遇到大模型-毁灭-还是重生" tabindex="-1">直播回放 | 当架构遇到大模型：毁灭，还是重生 <a class="header-anchor" href="#直播回放-当架构遇到大模型-毁灭-还是重生" aria-label="Permalink to &quot;直播回放 | 当架构遇到大模型：毁灭，还是重生&quot;">​</a></h1><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%99%BA%E8%83%BD%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98/images/%25E7%259B%25B4%25E6%2592%25AD%25E5%259B%259E%25E6%2594%25BE/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%99%BA%E8%83%BD%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98/images/%25E7%259B%25B4%25E6%2592%25AD%25E5%259B%259E%25E6%2594%25BE/1.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%99%BA%E8%83%BD%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98/images/%25E7%259B%25B4%25E6%2592%25AD%25E5%259B%259E%25E6%2594%25BE/2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%99%BA%E8%83%BD%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98/images/%25E7%259B%25B4%25E6%2592%25AD%25E5%259B%259E%25E6%2594%25BE/2.jpeg" alt=""></a></p><p>本次直播，你将获得：</p><ul><li><p>智能化时代，架构应如何重构？</p></li><li><p>智能体兴起，带来什么新范式？</p></li><li><p>新一代中台，应如何重新定义？</p></li></ul><h3 id="技术演进的本质" tabindex="-1">技术演进的本质 <a class="header-anchor" href="#技术演进的本质" aria-label="Permalink to &quot;技术演进的本质&quot;">​</a></h3><p>人类技术发展经历了六个时代，核心驱动力是技术本身，而非业务。</p><p>技术演进的两个关键维度是工具与链接。</p><ul><li><p>工具趋势：算力需求越来越高、智能程度不断提升（从简单机械到可感知、学习、决策的智能体）。</p></li><li><p>链接趋势：信息流转速度加快、主动性增强（从人驱动到数据 / 智能自主驱动）。</p></li></ul><p>技术的本质是重塑人与工具、工具与工具之间的信息流关系。</p><h3 id="架构与智能化的融合" tabindex="-1">架构与智能化的融合 <a class="header-anchor" href="#架构与智能化的融合" aria-label="Permalink to &quot;架构与智能化的融合&quot;">​</a></h3><p>智能化的本质是“工具自主驱动”，取代人类执行任务。企业架构的本质同样是构建人与虚拟工具（微服务、数据、系统等）之间的关系网络。二者本质一致，均为信息流交互，因此可以融合形成智能原生架构。</p><p>智能原生架构的目标是将高阶知识型信息流（由大模型携带）融入传统低阶数据 / 指令流中，统一规划信息的产生、转化与处理。</p><h3 id="大模型对架构的影响-重生而非毁灭" tabindex="-1">大模型对架构的影响：重生而非毁灭 <a class="header-anchor" href="#大模型对架构的影响-重生而非毁灭" aria-label="Permalink to &quot;大模型对架构的影响：重生而非毁灭&quot;">​</a></h3><ul><li><p>面对“大模型是否毁灭架构”的争议，观点为：架构迎来重生。</p></li><li><p>理由：智能化使系统关系网络更复杂（如现代化城市 vs 贫民窟），架构设计难度提升，架构师价值反而增大。</p></li></ul><h3 id="传统架构的痛点分析" tabindex="-1">传统架构的痛点分析 <a class="header-anchor" href="#传统架构的痛点分析" aria-label="Permalink to &quot;传统架构的痛点分析&quot;">​</a></h3><ul><li><p>业务响应力问题：研发门槛高、能力复用弱、变更影响大 → 根源在于软件形态、封闭开发、模块化不足。</p></li><li><p>业务体验性问题：交互体验落后、数字化深度不足、智能化不足 → 归结为信息流中的冗余、断点与摩擦。</p></li></ul><h3 id="智能原生架构方法论-四维框架重构" tabindex="-1">智能原生架构方法论（四维框架重构） <a class="header-anchor" href="#智能原生架构方法论-四维框架重构" aria-label="Permalink to &quot;智能原生架构方法论（四维框架重构）&quot;">​</a></h3><p>尽管仍采用业务、应用、数据、技术四层架构，但各层均进行重构：</p><ul><li><p>业务架构：融合通用思想，提出新型业务中台建设思路。</p></li><li><p>应用架构：引入智能体为核心单元，反思微服务本质，提出面向智能体的设计理念。</p></li><li><p>数据架构：提出双层价值模型，转向以价值为导向的设计，打破数据孤岛。</p></li><li><p>技术架构：强调思想误区剖析，如数字化落地效果差的原因。</p></li></ul><h3 id="智能体的本质与设计范式" tabindex="-1">智能体的本质与设计范式 <a class="header-anchor" href="#智能体的本质与设计范式" aria-label="Permalink to &quot;智能体的本质与设计范式&quot;">​</a></h3><p>智能体定义：将感知、决策、执行三阶段无缝串联，核心是决策（不限于大模型）。</p><p>智能体是概念，非技术绑定。即使未使用大模型（如推荐广告系统），只要具备感知 - 决策 -执行闭环，即为智能体。</p><p>面向智能体设计是一种设计范式演进：</p><ul><li><p>从面向过程、面向对象、SOA/ 微服务到智能体，本质是“分而治之”（拆解 + 组合）。</p></li><li><p>智能体设计的作用层级更广，可应用于函数、应用、领域乃至整个生态。</p></li><li><p>这是一种深远的设计变革，将会影响所有层级。</p></li></ul><h3 id="新一代中台建设" tabindex="-1">新一代中台建设 <a class="header-anchor" href="#新一代中台建设" aria-label="Permalink to &quot;新一代中台建设&quot;">​</a></h3><h3 id="业务中台" tabindex="-1">业务中台 <a class="header-anchor" href="#业务中台" aria-label="Permalink to &quot;业务中台&quot;">​</a></h3><ul><li><p>传统模式：从具体业务流程中抽象共性能力 → 导致烟囱式系统与信息孤岛。</p></li><li><p>新模式（受大模型启发）：先构建通用原子能力层，再支撑各专用场景。</p></li><li><p>核心转变：从“能力复用”到“能力生长性与滋养性”。</p></li></ul><h3 id="数据中台" tabindex="-1">数据中台 <a class="header-anchor" href="#数据中台" aria-label="Permalink to &quot;数据中台&quot;">​</a></h3><ul><li><p>传统问题：数据沦为应用架构的附庸。</p></li><li><p>大模型启发：打破“空间边界”概念（如 token 无边界）。</p></li><li><p>新思路：强调数据底层一致性，从源头保障主数据一致，避免后期转换摩擦。</p></li><li><p>设计原则：无边界思维应贯穿数据架构设计。</p></li></ul><h3 id="关键趋势与思想" tabindex="-1">关键趋势与思想 <a class="header-anchor" href="#关键趋势与思想" aria-label="Permalink to &quot;关键趋势与思想&quot;">​</a></h3><ul><li><p>叙事逻辑：从流程叙事转向数据叙事。</p></li><li><p>驱动逻辑：从人驱动 → 数据驱动 → 知识驱动（含模型驱动、目标驱动）。</p></li><li><p>处理模式：从批处理到流处理。</p></li><li><p>信息演进：从数据 → 信息 → 知识的转化是智能化关键。</p></li></ul><h3 id="架构演进策略" tabindex="-1">架构演进策略 <a class="header-anchor" href="#架构演进策略" aria-label="Permalink to &quot;架构演进策略&quot;">​</a></h3><ul><li><p>不应全盘推翻旧架构，而应逐步演进。</p></li><li><p>可选取主数据、跨系统共享数据等作为试点，验证新模式后再推广。</p></li></ul><h3 id="架构师的未来" tabindex="-1">架构师的未来 <a class="header-anchor" href="#架构师的未来" aria-label="Permalink to &quot;架构师的未来&quot;">​</a></h3><ul><li><p>新技能重点：理解智能体等新技术，但更应掌握其背后的设计思想。</p></li><li><p>核心能力：思想驱动设计，而非工具堆砌；深入理解业务逻辑与企业诉求。</p></li><li><p>职业前景：初级架构师不应恐慌，大模型无法替代对业务深度理解与架构思想融合的能力，架构师将更加稀缺。</p></li></ul>',36)])])}const c=e(r,[["render",n]]);export{d as __pageData,c as default};
